// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MONEY_BOX c;

    function setUp() public {
        c = new MONEY_BOX();
    }

    function _run(uint256 priorLock, uint256 depositAmt, uint256 collectAmt) internal {
        depositAmt = bound(depositAmt, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= depositAmt);
        bool depReverted;
        try c.Put{value: depositAmt}(priorLock) {
            depReverted = false;
        } catch {
            depReverted = true;
        }
        uint256 beforeUnlock;
        uint256 beforeRecBalance;
        try c.Acc(address(this)) returns (uint256 __r0, uint256 __r1) { beforeUnlock = __r0; beforeRecBalance = __r1; } catch { return; }
        uint beforeContractBalance = address(c).balance;
        uint beforeSelf = address(this).balance;
        bool collectReverted;
        try c.Collect(collectAmt) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }
        uint256 afterUnlock;
        uint256 afterRecBalance;
        try c.Acc(address(this)) returns (uint256 __r0, uint256 __r1) { afterUnlock = __r0; afterRecBalance = __r1; } catch { return; }
        uint afterContractBalance = address(c).balance;
        uint afterSelf = address(this).balance;
        uint decreased = 0;
        if (beforeRecBalance > afterRecBalance) {
            decreased = beforeRecBalance - afterRecBalance;
        }
        assertTrue(collectReverted || (
                // if recorded balance decreased, the external balance increased exactly by that amount
                (decreased == 0) || (
                    afterSelf == beforeSelf + decreased
                    && beforeContractBalance >= afterContractBalance
                    && (beforeContractBalance - afterContractBalance) >= decreased
                )
            ));
    }

    function testFuzz_run(uint256 priorLock, uint256 depositAmt, uint256 collectAmt) public {
        _run(priorLock, depositAmt, collectAmt);
    }

    receive() external payable {}
}
